void huffman_decode_init(huffman_decode_ctx *ctx) {
    ctx->fstate = 0;
    ctx->flags  = HUFFMAN_FLAG_ACCEPTED;
}

int huffman_decode_str(huffman_decode_ctx *ctx, uint8_t *dest,
                        const uint8_t *src, size_t srclen, int fin) {
    uint8_t *p = dest;
    const uint8_t *end = src + srclen;
    huffman_decode_node t = { .fstate = ctx->fstate, .flags = ctx->flags };

    for (; src != end;) {
        uint8_t c = *src++;
        t = huffman_decode_table[t.fstate][c >> 4];
        if (t.flags & HUFFMAN_FLAG_SYM) *p++ = t.sym;
        t = huffman_decode_table[t.fstate][c & 0xFU];
        if (t.flags & HUFFMAN_FLAG_SYM) *p++ = t.sym;
    }

    ctx->fstate = t.fstate;
    ctx->flags  = t.flags;

    if (fin && !(ctx->flags & HUFFMAN_FLAG_ACCEPTED))
        return -1;
    return (int)(p - dest);
}

int huffman_decode_failure(const huffman_decode_ctx *ctx) {
    return ctx->fstate == 0x100U;
}
